<template><AppLayout><div class="space-y-6"><div><h1 class="text-xl font-semibold">{{ t('marketplace.destinations') }}</h1><p class="mt-1 text-sm text-gray-500">{{ t('marketplace.destinationDescription') }}</p></div>
<p v-if="error" role="alert" class="text-sm text-red-700">{{ error }} <button class="underline" @click="load">{{ t('marketplace.retry') }}</button></p><p v-if="securityRequired" class="text-sm"><RouterLink to="/profile" class="text-primary-600 underline">{{ t('marketplace.setupSecurity') }}</RouterLink></p>
<section class="card p-6"><h2 class="font-semibold">{{ t('marketplace.savedDestinations') }}</h2><p v-if="loading" class="mt-3">{{ t('marketplace.loading') }}</p><p v-else-if="!destinations.length" class="mt-3 text-sm text-gray-500">{{ t('marketplace.noDestinations') }}</p><ul v-else class="mt-3 divide-y dark:divide-dark-600"><li v-for="d in destinations" :key="d.id" class="flex flex-wrap justify-between gap-2 py-3"><span>{{ d.masked_label }}</span><span class="text-sm text-gray-500">{{ d.verified ? t('marketplace.verified') : t('marketplace.awaitingVerification') }} · {{ t('marketplace.version') }} {{ d.version }}</span></li></ul></section>
<section class="card space-y-4 p-6"><h2 class="font-semibold">{{ t('marketplace.addDestination') }}</h2><p class="text-sm text-gray-500">{{ t('marketplace.destinationSecretHint') }}</p><p v-if="unknownKey" role="alert" class="text-sm text-amber-700">{{ t('marketplace.operationUnknown') }} <button class="underline" :disabled="busy" @click="checkOperation">{{ t('marketplace.checkStatus') }}</button> <button v-if="pendingPayload && checkedNotFound" class="ml-2 underline" :disabled="busy" @click="retryOperation">{{ t('marketplace.retrySameOperation') }}</button> <span v-if="checkedNotFound && !pendingPayload">{{ t('marketplace.destinationRecoveryHelp') }}</span></p><label class="block text-sm">{{ t('marketplace.maskedLabel') }}<input v-model.trim="label" :disabled="!!unknownKey || busy" data-test="label" class="input mt-1" autocomplete="off" /></label><label class="block text-sm">{{ t('marketplace.destinationCredential') }}<input v-model="credential" :disabled="!!unknownKey || busy" data-test="credential" type="password" class="input mt-1" autocomplete="off" /></label><button data-test="save" class="btn btn-primary" :disabled="busy || !!unknownKey || !label || !credential || label.includes(credential)" @click="save">{{ t('marketplace.save') }}</button></section><TotpStepUpDialog :controller="stepUp" /></div></AppLayout></template>
<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'
import { useAuthStore } from '@/stores/auth'
import { useStepUp, isStepUpCancelled } from '@/composables/useStepUp'
import { useWorkModeStore } from '@/stores/workMode'
import { listDestinations, createDestination, getDestinationOperation } from '@/api/supplier'
import type { PayoutDestination } from '@/types/marketplace'
const { t } = useI18n(); const stepUp = useStepUp(); const workMode = useWorkModeStore(); const auth = useAuthStore()
const operationStorage = `supplier-destination-operation:${auth.user?.id}`
const loading = ref(true); const busy = ref(false); const error = ref(''); const securityRequired = ref(false); const destinations = ref<PayoutDestination[]>([])
const label = ref(''); const credential = ref(''); const unknownKey = ref(sessionStorage.getItem(operationStorage) || '')
const checkedNotFound = ref(false)
const pendingPayload = ref<{ masked_label: string; credential: string } | null>(null)
watch([label, credential], () => { workMode.dirty = !!(label.value || credential.value) })
function beforeUnload(event: BeforeUnloadEvent) { if (workMode.dirty) { event.preventDefault(); event.returnValue = '' } }
async function load() { loading.value = true; error.value = ''; try { destinations.value = await listDestinations() } catch { error.value = t('marketplace.loadFailed') } finally { loading.value = false } }
async function save() { if (busy.value || unknownKey.value || !label.value || !credential.value || label.value.includes(credential.value)) return; pendingPayload.value = { masked_label: label.value, credential: credential.value }; credential.value = ''; await sendRequest(crypto.randomUUID()) }
async function sendRequest(key: string) { if (!pendingPayload.value || busy.value) return; busy.value = true; const payload = pendingPayload.value; try { await stepUp.run(() => createDestination(payload, key)); label.value = ''; payload.credential = ''; pendingPayload.value = null; unknownKey.value = ''; sessionStorage.removeItem(operationStorage); await load() } catch (e) { const err = e as { status?: number; code?: string; reason?: string }; if (isStepUpCancelled(e)) { payload.credential = ''; pendingPayload.value = null; return } if ((err.code === 'STEP_UP_TOTP_NOT_ENABLED' || err.reason === 'STEP_UP_TOTP_NOT_ENABLED')) { securityRequired.value = true; payload.credential = ''; pendingPayload.value = null } else if (!err.status || err.status >= 500 || err.status === 409) { unknownKey.value = key; checkedNotFound.value = false; sessionStorage.setItem(operationStorage, key) } else { payload.credential = ''; pendingPayload.value = null; error.value = t('marketplace.submitFailed') } } finally { busy.value = false } }
async function retryOperation() { if (unknownKey.value && pendingPayload.value && checkedNotFound.value) await sendRequest(unknownKey.value) }
async function checkOperation() { busy.value = true; try { const op = await getDestinationOperation(unknownKey.value); checkedNotFound.value = op.operation_status === 'not_found'; if (op.operation_status === 'completed' && op.destination_id) { unknownKey.value = ''; sessionStorage.removeItem(operationStorage); if (pendingPayload.value) pendingPayload.value.credential = ''; pendingPayload.value = null; label.value = ''; await load() } } catch { error.value = t('marketplace.operationUnknown') } finally { busy.value = false } }
onMounted(() => { void load(); window.addEventListener('beforeunload', beforeUnload) }); onUnmounted(() => { credential.value = ''; if (pendingPayload.value) pendingPayload.value.credential = ''; workMode.dirty = false; window.removeEventListener('beforeunload', beforeUnload) })
</script>
